CREATE TABLE IF NOT EXISTS mp2.envelopes (source String, stream String, schema_version UInt8, recv_ts DateTime64(3, 'UTC'), payload String) ENGINE = Null;  -- 저장하지 않는다. 원본은 파일, 파싱 결과는 MV 가 raw_* 로

CREATE MATERIALIZED VIEW IF NOT EXISTS mp2.mv_raw_upbit_trades TO mp2.raw_upbit_trades AS
    SELECT
        JSONExtractString(payload, 'cd') AS market,
        fromUnixTimestamp64Milli(JSONExtractInt(payload, 'ttms'), 'UTC') AS trade_ts,
        JSONExtractUInt(payload, 'sid') AS sequential_id,
        toDecimal128(JSONExtractRaw(payload, 'tp'), 8) AS price,
        toDecimal128(JSONExtractRaw(payload, 'tv'), 8) AS volume,
        JSONExtractString(payload, 'ab') AS ask_bid,
        if(JSONHas(payload, 'bap') AND JSONExtractRaw(payload, 'bap') != 'null', toDecimal128(JSONExtractRaw(payload, 'bap'), 8), NULL) AS best_ask_price,
        if(JSONHas(payload, 'bas') AND JSONExtractRaw(payload, 'bas') != 'null', toDecimal128(JSONExtractRaw(payload, 'bas'), 8), NULL) AS best_ask_size,
        if(JSONHas(payload, 'bbp') AND JSONExtractRaw(payload, 'bbp') != 'null', toDecimal128(JSONExtractRaw(payload, 'bbp'), 8), NULL) AS best_bid_price,
        if(JSONHas(payload, 'bbs') AND JSONExtractRaw(payload, 'bbs') != 'null', toDecimal128(JSONExtractRaw(payload, 'bbs'), 8), NULL) AS best_bid_size,
        fromUnixTimestamp64Milli(JSONExtractInt(payload, 'tms'), 'UTC') AS exchange_ts,
        recv_ts AS recv_ts
    FROM mp2.envelopes
    WHERE source = 'upbit' AND stream = 'trades' AND JSONExtractString(payload, 'ty') = 'trade';

CREATE MATERIALIZED VIEW IF NOT EXISTS mp2.mv_raw_upbit_orderbook TO mp2.raw_upbit_orderbook AS
    SELECT
        JSONExtractString(payload, 'cd') AS market,
        fromUnixTimestamp64Milli(JSONExtractInt(payload, 'tms'), 'UTC') AS ts,
        JSONExtractFloat(payload, 'lv') AS level,
        JSONExtractFloat(payload, 'tas') AS total_ask_size,
        JSONExtractFloat(payload, 'tbs') AS total_bid_size,
        arrayMap(u -> JSONExtractFloat(u, 'ap'), JSONExtractArrayRaw(payload, 'obu')) AS ask_prices,
        arrayMap(u -> JSONExtractFloat(u, 'as'), JSONExtractArrayRaw(payload, 'obu')) AS ask_sizes,
        arrayMap(u -> JSONExtractFloat(u, 'bp'), JSONExtractArrayRaw(payload, 'obu')) AS bid_prices,
        arrayMap(u -> JSONExtractFloat(u, 'bs'), JSONExtractArrayRaw(payload, 'obu')) AS bid_sizes,
        if(JSONHas(payload, 'st') AND JSONExtractString(payload, 'st') != '', JSONExtractString(payload, 'st'), 'REALTIME') AS stream_type,
        recv_ts AS recv_ts
    FROM mp2.envelopes
    WHERE source = 'upbit' AND stream = 'orderbook' AND JSONExtractString(payload, 'ty') = 'orderbook';

CREATE MATERIALIZED VIEW IF NOT EXISTS mp2.mv_raw_binance_trades TO mp2.raw_binance_trades AS
    SELECT
        JSONExtractString(payload, 's') AS symbol,
        JSONExtractUInt(payload, 't') AS trade_id,
        fromUnixTimestamp64Milli(JSONExtractInt(payload, 'T'), 'UTC') AS trade_ts,
        toDecimal128(JSONExtractString(payload, 'p'), 8) AS price,
        toDecimal128(JSONExtractString(payload, 'q'), 8) AS qty,
        toUInt8(JSONExtractBool(payload, 'm')) AS is_buyer_maker,
        fromUnixTimestamp64Milli(JSONExtractInt(payload, 'E'), 'UTC') AS event_ts,
        recv_ts AS recv_ts
    FROM mp2.envelopes
    WHERE source = 'binance' AND stream = 'trades' AND JSONExtractString(payload, 'e') = 'trade';

CREATE MATERIALIZED VIEW IF NOT EXISTS mp2.mv_raw_binance_depth TO mp2.raw_binance_depth AS
    SELECT
        JSONExtractString(payload, 's') AS symbol,
        if(JSONExtractString(payload, 'e') = 'snapshot', 'snapshot', 'diff') AS kind,
        if(JSONExtractString(payload, 'e') = 'snapshot', JSONExtractUInt(payload, 'lastUpdateId'), JSONExtractUInt(payload, 'U')) AS first_update_id,
        if(JSONExtractString(payload, 'e') = 'snapshot', JSONExtractUInt(payload, 'lastUpdateId'), JSONExtractUInt(payload, 'u')) AS last_update_id,
        if(JSONHas(payload, 'E'), fromUnixTimestamp64Milli(JSONExtractInt(payload, 'E'), 'UTC'), recv_ts) AS event_ts,
        arrayMap(x -> toFloat64(JSONExtractString(x, 1)), JSONExtractArrayRaw(payload, if(JSONExtractString(payload, 'e') = 'snapshot', 'bids', 'b'))) AS bid_prices,
        arrayMap(x -> toFloat64(JSONExtractString(x, 2)), JSONExtractArrayRaw(payload, if(JSONExtractString(payload, 'e') = 'snapshot', 'bids', 'b'))) AS bid_sizes,
        arrayMap(x -> toFloat64(JSONExtractString(x, 1)), JSONExtractArrayRaw(payload, if(JSONExtractString(payload, 'e') = 'snapshot', 'asks', 'a'))) AS ask_prices,
        arrayMap(x -> toFloat64(JSONExtractString(x, 2)), JSONExtractArrayRaw(payload, if(JSONExtractString(payload, 'e') = 'snapshot', 'asks', 'a'))) AS ask_sizes,
        recv_ts AS recv_ts
    FROM mp2.envelopes
    WHERE source = 'binance' AND stream = 'depth' AND JSONExtractString(payload, 'e') IN ('depthUpdate', 'snapshot');
